const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { resolve } = require('../js/prototype-weather.js');
const weather = require('../js/prototype-weather.js');
const projectUi = fs.readFileSync(path.join(__dirname, '../js/prototype-project-ui.js'), 'utf8');
assert.match(projectUi, /prototypeWeatherProvince/);
assert.match(projectUi, /weatherReference/);
assert.match(projectUi, /data-weather-preview=/);
const locations = weather.getLocations();
assert.equal(locations.length, 295);
assert.equal(new Set(locations.map(row => [row.province,row.city,row.station].join('\u0000'))).size, locations.length);
const beijingIndex = locations.findIndex(row => row.province === '北京' && row.city === '北京');
assert.deepEqual(weather.referenceForLocation(String(beijingIndex)), { province:'北京', city:'北京', station:locations[beijingIndex].station || '' });
assert.equal(weather.referenceForLocation(''), null);
assert.equal(weather.referenceForLocation('not-a-location'), null);
let r = resolve({ location:'北京', weatherReference:{province:'北京',city:'北京'} }, {});
assert.equal(r.usageLocation, '北京 北京');
assert.deepEqual(r.winter, {dryBulb:-9.9,rh:44});
assert.deepEqual(r.summer, {dryBulb:33.5,wetBulb:26.4});
assert.equal(r.source, 'user-supplied-derived-workbook');
r = resolve({ location:'不存在', weatherReference:{city:'不存在'} }, {});
assert.equal(r.status, 'unknown');
r = resolve({}, {});
assert.equal(r.status, 'blank');
r = resolve({ location:'北京', weatherReference:{city:'北京'} }, {weatherOverride:{winter:{dryBulb:-5,rh:50},summer:{dryBulb:30,wetBulb:24}}});
assert.equal(r.status, 'manual'); assert.equal(r.usageLocation, '已手动修改'); assert.equal(r.manualModified, true); assert.equal(r.winter.rh, 50);
r = resolve({ location:'北京', weatherReference:{city:'北京'} }, {weatherOverride:{winterAirConditioningTemperature:{value:-3,source:'user'},winterAirConditioningRH:{value:40,source:'user'},summerAirConditioningDryBulb:{value:31,source:'user'},summerAirConditioningWetBulb:{value:23,source:'user'}}});
assert.equal(r.status, 'manual'); assert.equal(r.usageLocation, '已手动修改'); assert.deepEqual(r.winter,{dryBulb:-3,rh:40}); assert.deepEqual(r.summer,{dryBulb:31,wetBulb:23});
r = resolve({ location:'北京', weatherReference:{city:'北京'} }, {weatherOverride:{winterAirConditioningTemperature:'',winterAirConditioningRH:'',summerAirConditioningDryBulb:'',summerAirConditioningWetBulb:''}});
assert.deepEqual(r.winter,{dryBulb:-9.9,rh:44}); assert.deepEqual(r.summer,{dryBulb:33.5,wetBulb:26.4}); assert.equal(r.manualModified,false);
r = resolve({ location:'上海市浦东新区', weatherReference:'用户说明', conditions:{winterOutdoorDryBulb:-2,outdoorRH:60,summerOutdoorDryBulb:35,summerOutdoorWetBulb:28} }, {});
assert.equal(r.usageLocation,'上海市浦东新区'); assert.equal(r.status,'unknown'); assert.equal(r.winter.dryBulb,-2); assert.match(r.note,/未在气象库/);
r = resolve({ weatherReference:{city:'北京'}, conditions:{winterOutdoorDryBulb:-10,outdoorRH:45,summerOutdoorDryBulb:32,summerOutdoorWetBulb:25} }, {});
assert.deepEqual(r.winter,{dryBulb:-10,rh:45});
r = resolve({ location:'北京', weatherReference:{city:'北京'}, weatherOverride:{ summerAirConditioningDryBulb:{value:30,source:'项目手动调整'}, winterAirConditioningRH:{value:55,source:'项目手动调整'} } }, { weatherOverride:{ winterAirConditioningTemperature:{value:-3,source:'机组手动调整'} } });
assert.deepEqual(r.winter,{dryBulb:-3,rh:55}); assert.deepEqual(r.summer,{dryBulb:30,wetBulb:26.4});
assert.equal(r.projectManualModified,true); assert.equal(r.manualModified,true);
r = resolve({ location:'北京', weatherReference:{city:'北京'}, weatherOverride:{winterAirConditioningRH:{value:101,source:'项目手动调整'},summerAirConditioningWetBulb:{value:0,source:'项目手动调整'}} }, {});
assert.equal(r.winter.rh,44); assert.equal(r.summer.wetBulb,0); assert.equal(r.projectManualModified,true);
r = resolve({ location:'不存在', weatherReference:{city:'不存在'}, weatherOverride:{winterAirConditioningTemperature:{value:0,source:'项目手动调整'}} }, {});
assert.equal(r.winter.dryBulb,0); assert.equal(r.projectManualModified,true);
r = resolve({ location:'北京', weatherReference:{city:'北京'}, weatherOverride:{winterAirConditioningTemperature:{value:'',source:'项目手动调整'}} }, {});
assert.equal(r.winter.dryBulb,-9.9); assert.equal(r.projectManualModified,false);
// No station: a valid project manual value remains effective and is not blocked by lookup status.
r = resolve({ location:'不存在', weatherReference:{city:'不存在'}, weatherOverride:{summerAirConditioningDryBulb:{value:29,source:'项目手动调整'}} }, {});
assert.equal(r.summer.dryBulb,29); assert.equal(r.status,'manual');
console.log('通过：天气精确匹配、空白/未知地区、项目快照与机组手动覆盖测试。');
